(811275, 91052, 21478, '<td valign="top">Difficult to get good focus with this closeup (text seems blurry) the depth of field makes this tough to view.</td>', 'Difficult to get good focus with this closeup (text seems blurry) the depth of field makes this tough to view.', '2004-07-14 14:49:29.000000', NULL, 1),
(811277, 90842, 21478, '<td valign="top">Very clever</td>', 'Very clever', '2004-07-14 14:49:49.000000', NULL, 1),
(811282, 89986, 21478, '<td valign="top">Not sharp enough.</td>', 'Not sharp enough.', '2004-07-14 14:50:53.000000', NULL, 1),
