(811285, 91117, 21478, '<td valign="top">great color and composition.</td>', 'great color and composition.', '2004-07-14 14:51:53.000000', NULL, 1),
(811286, 90598, 21478, '<td valign="top">Nice picture - just no words in it! (and a clever title doesn''t cut it if your image doesn''t meet the challenge - just my opinion).</td>', 'Nice picture - just no words in it! (and a clever title doesn''t cut it if your image doesn''t meet the challenge - just my opinion).', '2004-07-14 14:52:37.000000', NULL, 1),
(811288, 90215, 7252, '<td valign="top">A hyperfocal distance chart for your lens would make it much easier to get this shot. Without that, try a wide open aperture, a high fstop, and focus on the text and not the owl.</td>', 'A hyperfocal distance chart for your lens would make it much easier to get this shot. Without that, try a wide open aperture, a high fstop, and focus on the text and not the owl.', '2004-07-14 14:53:07.000000', NULL, 1),
(811289, 90700, 21478, '<td valign="top">great concept and well executed. this could have been a little better with more depth of field (ie. both words being in focus)</td>', 'great concept and well executed. this could have been a little better with more depth of field (ie. both words being in focus)', '2004-07-14 14:53:14.000000', NULL, 1),
(811292, 90517, 21478, '<td valign="top">sorry - even the word focus is not (in focus)</td>', 'sorry - even the word focus is not (in focus)', '2004-07-14 14:53:57.000000', NULL, 1),
