(811359, 90302, 23394, '<td valign="top">I can''t find any words, and I''m not really sure what this picture is about.  Not enough in focus.</td>', 'I can''t find any words, and I''m not really sure what this picture is about.  Not enough in focus.', '2004-07-14 15:41:17.000000', NULL, 1),
(811363, 90164, 23394, '<td valign="top">I see words, but do not see what they tie to in the picture.  Maybe with more context the picture could tell me its story?</td>', 'I see words, but do not see what they tie to in the picture.  Maybe with more context the picture could tell me its story?', '2004-07-14 15:42:10.000000', NULL, 1),
