(811654, 89743, 1922, '<td valign="top">Sad but no words.</td>', 'Sad but no words.', '2004-07-14 17:41:44.000000', NULL, 1),
(811655, 90840, 7322, '<td valign="top">"Take a photograph where complete words -- not just individual letters -- play a creative role in your composition."<br/> <br/>Where are the words and how do they play a creative role in this photograph?</td>', '"Take a photograph where complete words -- not just individual letters -- play a creative role in your composition." Where are the words and how do they play a creative role in this photograph?', '2004-07-14 17:42:04.000000', NULL, 1),
(811656, 90302, 1922, '<td valign="top">No words.</td>', 'No words.', '2004-07-14 17:42:13.000000', NULL, 1),
(811657, 91045, 22734, '<td valign="top">This is a great idea, but to have maintained a higher standing I would have made a wiser selection of words. My good marks are its concept and presentation.</td>', 'This is a great idea, but to have maintained a higher standing I would have made a wiser selection of words. My good marks are its concept and presentation.', '2004-07-14 17:42:14.000000', NULL, 1),
(811660, 91009, 14620, '<td valign="top">This is a really neat idea.  The color is great and the DOF is what really makes this shot.  Nice take on the challenge. :-)</td>', 'This is a really neat idea.  The color is great and the DOF is what really makes this shot.  Nice take on the challenge. :-)', '2004-07-14 17:42:32.000000', NULL, 1),
(811661, 89932, 22734, '<td valign="top">Nice doagonal effect with nice texture.</td>', 'Nice doagonal effect with nice texture.', '2004-07-14 17:43:32.000000', NULL, 1),
(811664, 91027, 1922, '<td valign="top">Cool photo! I like this effect.</td>', 'Cool photo! I like this effect.', '2004-07-14 17:45:09.000000', NULL, 1),
(811665, 90726, 14620, '<td valign="top">What an excellent composition!  Great lighting and wonderful subject.  Don''t know that there''d be anything to change.  Very nice job!</td>', 'What an excellent composition!  Great lighting and wonderful subject.  Don''t know that there''d be anything to change.  Very nice job!', '2004-07-14 17:45:15.000000', NULL, 1),
(811666, 90244, 7322, '<td valign="top">"Take a photograph where complete words -- not just individual letters -- play a creative role in your composition."<br/> <br/>  I don''t see anything creative in this literal, close-up  representation of an old pound note. There is nothing of actual artistic merit that the photographer can take credit for. Technically, it is fairly sharp  but there is no outside context to create a meaningful experience for the viewer except to show what a 1953 Australian one pound note looks like.</td>', '"Take a photograph where complete words -- not just individual letters -- play a creative role in your composition."   I don''t see anything creative in this literal, close-up  representation of an old pound note. There is nothing of actual artistic merit that the photographer can take credit for. Technically, it is fairly sharp  but there is no outside context to create a meaningful experience for the viewer except to show what a 1953 Australian one pound note looks like.', '2004-07-14 17:45:54.000000', NULL, 1),
(811668, 90460, 14620, '<td valign="top">Fantastic shot and wonderful idea!  The toads seem a little oversharpened or something but this shot is too good to mark down for that.  Great job!</td>', 'Fantastic shot and wonderful idea!  The toads seem a little oversharpened or something but this shot is too good to mark down for that.  Great job!', '2004-07-14 17:46:33.000000', NULL, 1),
(811669, 91090, 7322, '<td valign="top">Other than identifying the origins of the plane I don''t find that the words play a creative role in this rather literal representation of the plane.</td>', 'Other than identifying the origins of the plane I don''t find that the words play a creative role in this rather literal representation of the plane.', '2004-07-14 17:47:04.000000', NULL, 1),
(811670, 91043, 14620, '<td valign="top">Beautiful!  Nice use of DOF and the composition is pretty much perfect.</td>', 'Beautiful!  Nice use of DOF and the composition is pretty much perfect.', '2004-07-14 17:47:28.000000', NULL, 1),
(811674, 90751, 14620, '<td valign="top">Wonderful lighting and great clarity in this shot.  I really like the perspective you''ve chosen and the B&amp;W treatment is perfect!  Nice job!</td>', 'Wonderful lighting and great clarity in this shot.  I really like the perspective you''ve chosen and the B&W treatment is perfect!  Nice job!', '2004-07-14 17:48:36.000000', NULL, 1),
(811677, 89743, 21362, '<td valign="top">Wow, interesting photo! But "words?"</td>', 'Wow, interesting photo! But "words?"', '2004-07-14 17:49:10.000000', NULL, 1),
(811678, 91098, 1922, '<td valign="top">Very nice photo! I think with a little more focal depth with the flower in focus this could be even better.</td>', 'Very nice photo! I think with a little more focal depth with the flower in focus this could be even better.', '2004-07-14 17:49:14.000000', NULL, 1),
(811679, 90754, 7322, '<td valign="top">Good subject matter but you need a tripod to avoid the camera shake.</td>', 'Good subject matter but you need a tripod to avoid the camera shake.', '2004-07-14 17:49:27.000000', NULL, 1),
(811680, 91031, 14620, '<td valign="top">Fantastic!!! What a find.  This is a great shot with very good composition.  Very nice B&amp;W treatment.</td>', 'Fantastic!!! What a find.  This is a great shot with very good composition.  Very nice B&W treatment.', '2004-07-14 17:49:39.000000', NULL, 1),
