(811691, 90840, 16126, '<td valign="top">Doesn''t meet the challenge</td>', 'Doesn''t meet the challenge', '2004-07-14 17:56:33.000000', NULL, 1),
(811692, 90840, 18708, '<td valign="top">sorry I don''t get it.</td>', 'sorry I don''t get it.', '2004-07-14 17:57:12.000000', NULL, 1),
(811698, 91049, 7322, '<td valign="top">Was cropping off the C in Icecream intentional or just random, I wonder? I got a laugh out of reading "Ream Co." but since the title was "We freeze to please" I don''t think the humor was intentional. But then there are those two tiny oranges, or tomatos or whatever,  so I''m confused again. <br/> <br/>I guess the intent just isn''t clear enough for me to evaluate. Graphically, it has some good qualities. I like the pastel colors of the building and door.</td>', 'Was cropping off the C in Icecream intentional or just random, I wonder? I got a laugh out of reading "Ream Co." but since the title was "We freeze to please" I don''t think the humor was intentional. But then there are those two tiny oranges, or tomatos or whatever,  so I''m confused again.  I guess the intent just isn''t clear enough for me to evaluate. Graphically, it has some good qualities. I like the pastel colors of the building and door.', '2004-07-14 17:59:24.000000', NULL, 1),
(811702, 91025, 1922, '<td valign="top">Neat idea. Good color but could be a little sharper.</td>', 'Neat idea. Good color but could be a little sharper.', '2004-07-14 18:01:21.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(811705, 91014, 7322, '<td valign="top">Where have I seen this before? This trick is getting tired for me. It''s a good shot so I have to give it at least a five but can this be the last one of these? Please?</td>', 'Where have I seen this before? This trick is getting tired for me. It''s a good shot so I have to give it at least a five but can this be the last one of these? Please?', '2004-07-14 18:01:26.000000', NULL, 1),
(811707, 90196, 10263, '<td valign="top">Interesting. I like it. Now I''m anxious to know how you got the neon words</td>', 'Interesting. I like it. Now I''m anxious to know how you got the neon words', '2004-07-14 18:02:30.000000', NULL, 1),
(811708, 91052, 1922, '<td valign="top">More depth might help but good.</td>', 'More depth might help but good.', '2004-07-14 18:03:26.000000', NULL, 1),
(811711, 91194, 16126, '<td valign="top">Creative idea, but the lighting could have been better. Maybe use a subject wearing a black sweater and then use one or more strong lamps instead of the flash?</td>', 'Creative idea, but the lighting could have been better. Maybe use a subject wearing a black sweater and then use one or more strong lamps instead of the flash?', '2004-07-14 18:04:09.000000', NULL, 1),
(811712, 91114, 20066, '<td valign="top">je ne comprend pas - mais ...  that photo is brilliant  !</td>', 'je ne comprend pas - mais ...  that photo is brilliant  !', '2004-07-14 18:04:29.000000', NULL, 1),
(811717, 91191, 1922, '<td valign="top">Ahhhhh! Great shot. Good lighting and sharp.</td>', 'Ahhhhh! Great shot. Good lighting and sharp.', '2004-07-14 18:07:26.000000', NULL, 1),
(811720, 90987, 1922, '<td valign="top">Nice lighting effect.</td>', 'Nice lighting effect.', '2004-07-14 18:08:24.000000', NULL, 1),
(811721, 91098, 10263, '<td valign="top">I like this one a lot. The colors, the subject and the clarity of the words are wonderful.</td>', 'I like this one a lot. The colors, the subject and the clarity of the words are wonderful.', '2004-07-14 18:09:28.000000', NULL, 1),
(811723, 90809, 16126, '<td valign="top">The connection to the challenge is rather weak, I can barely make out the words. But it''s a good image, strong impression on his face and hand, and a beautiful owl. 7</td>', 'The connection to the challenge is rather weak, I can barely make out the words. But it''s a good image, strong impression on his face and hand, and a beautiful owl. 7', '2004-07-14 18:10:36.000000', NULL, 1),
(811728, 91036, 1922, '<td valign="top">....and in record time I''d bet. Very nice photo. Well executed.</td>', '....and in record time I''d bet. Very nice photo. Well executed.', '2004-07-14 18:12:00.000000', NULL, 1),
(811730, 90737, 16126, '<td valign="top">Fun and creative idea! Would have like it even better if all the hands had been in focus.  Also slightly more cropping off on the right might have improved composition. 7</td>', 'Fun and creative idea! Would have like it even better if all the hands had been in focus.  Also slightly more cropping off on the right might have improved composition. 7', '2004-07-14 18:13:01.000000', NULL, 1),
(811731, 91044, 10263, '<td valign="top">Very clever. I would have prefered the rabbit more in focus and maybe show an ear or tail or something that shows rabbit traits. The tones are great :)</td>', 'Very clever. I would have prefered the rabbit more in focus and maybe show an ear or tail or something that shows rabbit traits. The tones are great :)', '2004-07-14 18:13:07.000000', NULL, 1),
(811733, 89926, 10263, '<td valign="top">Clever shot. I don''t care much for the border but the colors in the shot are good and the dark background works.</td>', 'Clever shot. I don''t care much for the border but the colors in the shot are good and the dark background works.', '2004-07-14 18:15:59.000000', NULL, 1),
(811734, 90196, 1922, '<td valign="top">Very cool effect. I like the lighting technique.</td>', 'Very cool effect. I like the lighting technique.', '2004-07-14 18:16:53.000000', NULL, 1),
(811735, 90288, 22046, '<td valign="top">This is a pretty picture and I''d give it a decent score except it totally misses the topic of the challenge. There are supposed to be words in the picture. Because it is well taken I am giving you a three. I wanted you to know why your score may be low in this challenge.</td>', 'This is a pretty picture and I''d give it a decent score except it totally misses the topic of the challenge. There are supposed to be words in the picture. Because it is well taken I am giving you a three. I wanted you to know why your score may be low in this challenge.', '2004-07-14 18:17:17.000000', NULL, 1),
(811738, 89853, 22262, '<td valign="top">Clever.  Fits the chalenge better than most.</td>', 'Clever.  Fits the chalenge better than most.', '2004-07-14 18:20:14.000000', NULL, 1),
(811739, 91074, 16126, '<td valign="top">Is only the only word you could come up with? :-))) Nice find, great colors. 8</td>', 'Is only the only word you could come up with? :-))) Nice find, great colors. 8', '2004-07-14 18:20:35.000000', NULL, 1),
(811741, 91194, 22046, '<td valign="top">I like your take on the challenge. Had to ask my husband who know ASL what the word was... it is of course "word". Should have known. ;)</td>', 'I like your take on the challenge. Had to ask my husband who know ASL what the word was... it is of course "word". Should have known. ;)', '2004-07-14 18:21:28.000000', NULL, 1),
(811745, 91193, 10263, '<td valign="top">I like the message... I am me above all else. The photo isn''t very clear. I don''t know where the dark lines around the hands and around the sign come from but hopefully some of the good photographers around here can tell you what it is and how to get rid of it :)</td>', 'I like the message... I am me above all else. The photo isn''t very clear. I don''t know where the dark lines around the hands and around the sign come from but hopefully some of the good photographers around here can tell you what it is and how to get rid of it :)', '2004-07-14 18:24:33.000000', NULL, 1),
(811748, 91096, 19184, '<td valign="top">Very nice macro, can see the details on the bug very well, maybe just a little sharper.  However, I fail to see how this fits in the words challenge.</td>', 'Very nice macro, can see the details on the bug very well, maybe just a little sharper.  However, I fail to see how this fits in the words challenge.', '2004-07-14 18:26:58.000000', NULL, 1),
