(812690, 89853, 22564, '<td valign="top">This one is really funny :)</td>', 'This one is really funny :)', '2004-07-15 10:46:34.000000', NULL, 1),
(812692, 90244, 19841, '<td valign="top">The cropping is a little off.  If you are doing a centered composition, you need to really center it.  The letters running off the right end spoil the effect.</td>', 'The cropping is a little off.  If you are doing a centered composition, you need to really center it.  The letters running off the right end spoil the effect.', '2004-07-15 10:51:33.000000', NULL, 1),
