INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(813028, 89853, 14603, '<td valign="top">You may lose points with some for the content but I think it`s been very well thought out and hilarious into the bargain.</td>', 'You may lose points with some for the content but I think it`s been very well thought out and hilarious into the bargain.', '2004-07-15 16:44:20.000000', NULL, 1),
(813036, 90559, 3087, '<td valign="top">Not really no. Not at all actually. But an interesting picture nonetheless.</td>', 'Not really no. Not at all actually. But an interesting picture nonetheless.', '2004-07-15 16:54:00.000000', NULL, 1),
(813038, 91114, 3087, '<td valign="top">Interesting image and I like the way the word "MEN" falls on his forehead. Nicely done.</td>', 'Interesting image and I like the way the word "MEN" falls on his forehead. Nicely done.', '2004-07-15 16:54:53.000000', NULL, 1),
(813039, 91015, 3087, '<td valign="top">Nice lighting - I like the way the shadows and background merge. Interesting shapes with the thumbs posed as they are too.</td>', 'Nice lighting - I like the way the shadows and background merge. Interesting shapes with the thumbs posed as they are too.', '2004-07-15 16:55:56.000000', NULL, 1),
(813043, 89838, 3087, '<td valign="top">A little too blown out towards the white but nice composition and idea.</td>', 'A little too blown out towards the white but nice composition and idea.', '2004-07-15 16:57:59.000000', NULL, 1),
(813044, 89840, 3087, '<td valign="top">Very creative and I do love how the shadows ARE the content and the object is almost invisible. Nicely done!</td>', 'Very creative and I do love how the shadows ARE the content and the object is almost invisible. Nicely done!', '2004-07-15 16:59:12.000000', NULL, 1),
(813050, 90358, 3087, '<td valign="top">Would prefer a less angled viewpoint though I appreciate it might not be possible. Nice colours and textures.</td>', 'Would prefer a less angled viewpoint though I appreciate it might not be possible. Nice colours and textures.', '2004-07-15 17:04:44.000000', NULL, 1),
(813052, 91035, 3087, '<td valign="top">What a powerful message he has written - very emotional image that really shows the emotions that can be conveyed in the written word.</td>', 'What a powerful message he has written - very emotional image that really shows the emotions that can be conveyed in the written word.', '2004-07-15 17:05:32.000000', NULL, 1),
(813053, 91150, 3087, '<td valign="top">A favourite poem, what a sweet way of presenting it!</td>', 'A favourite poem, what a sweet way of presenting it!', '2004-07-15 17:05:58.000000', NULL, 1),
(813059, 89863, 3087, '<td valign="top">That''s certainly an impressive sculpture but I think the wow factor comes from the artist''s creativity rather than yours.</td>', 'That''s certainly an impressive sculpture but I think the wow factor comes from the artist''s creativity rather than yours.', '2004-07-15 17:07:48.000000', NULL, 1),
(813064, 91021, 3087, '<td valign="top">Love the study of the pottery but the choice of background leaves a lot to be desired...</td>', 'Love the study of the pottery but the choice of background leaves a lot to be desired...', '2004-07-15 17:08:54.000000', NULL, 1),
(813066, 91052, 3087, '<td valign="top">Striking, could see this in a glossy advertisement. Not sure about point of focus and DOF choices and lighting seems uneven - background seems pinkey grey towards top. Definitely still striking though.</td>', 'Striking, could see this in a glossy advertisement. Not sure about point of focus and DOF choices and lighting seems uneven - background seems pinkey grey towards top. Definitely still striking though.', '2004-07-15 17:10:14.000000', NULL, 1),
(813068, 90460, 3087, '<td valign="top">Aaaw cute critters! This one''s a bit different! Think the frog at the left is too close to edge of frame - feels a touch unbalanced but generally like composition weighted in lower left corner.</td>', 'Aaaw cute critters! This one''s a bit different! Think the frog at the left is too close to edge of frame - feels a touch unbalanced but generally like composition weighted in lower left corner.', '2004-07-15 17:11:05.000000', NULL, 1),
(813071, 89940, 3087, '<td valign="top">I love this... it''s a quiet image with wonderful textures and colours. That tiny rusted sign is such a perfect focal point. Excellent!</td>', 'I love this... it''s a quiet image with wonderful textures and colours. That tiny rusted sign is such a perfect focal point. Excellent!', '2004-07-15 17:11:51.000000', NULL, 1),
(813072, 91045, 3087, '<td valign="top">Wow, this has such a lot of strength behind it. Very powerful. Image could be better - lighting, shadow on face, image quality. But content is disturbing - and striking an emotion like that is surely what was intended. Good one!</td>', 'Wow, this has such a lot of strength behind it. Very powerful. Image could be better - lighting, shadow on face, image quality. But content is disturbing - and striking an emotion like that is surely what was intended. Good one!', '2004-07-15 17:12:01.000000', NULL, 1),
(813074, 89944, 3087, '<td valign="top">Looks like a nice candid with a quirky juxtaposition of poster and person.</td>', 'Looks like a nice candid with a quirky juxtaposition of poster and person.', '2004-07-15 17:12:10.000000', NULL, 1),
(813075, 90726, 3087, '<td valign="top">Clever! Nicely lit and nicely composed.</td>', 'Clever! Nicely lit and nicely composed.', '2004-07-15 17:12:17.000000', NULL, 1),
(813076, 91031, 3087, '<td valign="top">How surreal. I do like the choice for stark black and white - contrasts quite well with the sugary content.</td>', 'How surreal. I do like the choice for stark black and white - contrasts quite well with the sugary content.', '2004-07-15 17:12:29.000000', NULL, 1),
(813077, 91027, 3087, '<td valign="top">WOW! This is beautiful! Don''t know how you created it but it''s really striking!</td>', 'WOW! This is beautiful! Don''t know how you created it but it''s really striking!', '2004-07-15 17:13:18.000000', NULL, 1),
(813079, 90598, 18708, '<td valign="top">I think that''s a stretch</td>', 'I think that''s a stretch', '2004-07-15 17:16:27.000000', NULL, 1),
(813085, 91187, 22011, '<td valign="top">''negative space'' (Gotta use the jargon...) at the bottom of this image dosn''t seem to work, a tighter crop woudl have been better.  Neat idea though, and well executed.</td>', '''negative space'' (Gotta use the jargon...) at the bottom of this image dosn''t seem to work, a tighter crop woudl have been better.  Neat idea though, and well executed.', '2004-07-15 17:20:56.000000', NULL, 1),
(813087, 90840, 22011, '<td valign="top">Not sure how this was meant to mean the challenge, and the bus isn''t even that tatty, That''d be a tidy mobile home in some parts of New Zealand :-).</td>', 'Not sure how this was meant to mean the challenge, and the bus isn''t even that tatty, That''d be a tidy mobile home in some parts of New Zealand :-).', '2004-07-15 17:22:30.000000', NULL, 1),
