(813444, 91030, 23394, '<td valign="top">while this is an interesting picture, i''m not sure how the words in the picture relate to the challenge</td>', 'while this is an interesting picture, i''m not sure how the words in the picture relate to the challenge', '2004-07-15 23:04:40.000000', NULL, 1),
(813448, 91036, 23394, '<td valign="top">ok, this took me a number of looks to ''get it''.  it might have been easier to get if you had put ''the world'' in caps and in quotes...<br/> <br/>title aside, this is a tough shot because it''s not easy to get an angle that allows both ships while not letting the larger one overwhelm the smaller one.</td>', 'ok, this took me a number of looks to ''get it''.  it might have been easier to get if you had put ''the world'' in caps and in quotes... title aside, this is a tough shot because it''s not easy to get an angle that allows both ships while not letting the larger one overwhelm the smaller one.', '2004-07-15 23:09:25.000000', NULL, 1),
(813457, 90391, 1368, '<td valign="top">I think this one could be a bit sharper and mabey more contrast or shadows on it, the composition is good though So you have good eye for this, good luck :)</td>', 'I think this one could be a bit sharper and mabey more contrast or shadows on it, the composition is good though So you have good eye for this, good luck :)', '2004-07-15 23:15:16.000000', NULL, 1),
(813459, 90825, 1368, '<td valign="top">The sky has a great blue color here, I feel that the thing in front of the building is a little distracting though and to be picky there is a small blown out spot in the right bottom corner, But good focus and clarity, Good luck :)</td>', 'The sky has a great blue color here, I feel that the thing in front of the building is a little distracting though and to be picky there is a small blown out spot in the right bottom corner, But good focus and clarity, Good luck :)', '2004-07-15 23:17:30.000000', NULL, 1),
(813462, 91012, 1368, '<td valign="top">I feel like the composition is a little off here, not much though it good really, But I think if you would have cropped from the left at the lighter it would have improved, lighting and focus are good except the had is a little grey, but I think the hand is good with no focus on it, Good luck</td>', 'I feel like the composition is a little off here, not much though it good really, But I think if you would have cropped from the left at the lighter it would have improved, lighting and focus are good except the had is a little grey, but I think the hand is good with no focus on it, Good luck', '2004-07-15 23:22:13.000000', NULL, 1),
(813464, 89944, 1368, '<td valign="top">Great composition and emotional picture :) I feel that the reflection of the car and some other guy in the window is a little distracting and the blown out spots on his shirt. good luck 7</td>', 'Great composition and emotional picture :) I feel that the reflection of the car and some other guy in the window is a little distracting and the blown out spots on his shirt. good luck 7', '2004-07-15 23:23:51.000000', NULL, 1),
(813465, 89992, 1368, '<td valign="top">The plain there looks cool, but I feel the composition is not really balanced it has all the stuff at the bottom and nothing to balance it so it feels almost like falling or something, I dont know but good focus and exposure Good luck :)</td>', 'The plain there looks cool, but I feel the composition is not really balanced it has all the stuff at the bottom and nothing to balance it so it feels almost like falling or something, I dont know but good focus and exposure Good luck :)', '2004-07-15 23:26:03.000000', NULL, 1),
(813468, 90635, 1368, '<td valign="top">I feel that the background here is too busy, could maybe be better to use shallow dof? maybe not, but the flash reflections on his head are a little distracting and I feel that there should be more space above his head and less space to the left of his head, but I know its not possible then the words hadnt come in, Good luck</td>', 'I feel that the background here is too busy, could maybe be better to use shallow dof? maybe not, but the flash reflections on his head are a little distracting and I feel that there should be more space above his head and less space to the left of his head, but I know its not possible then the words hadnt come in, Good luck', '2004-07-15 23:29:09.000000', NULL, 1),
(813478, 89832, 23899, '<td valign="top"><br/></td>', '', '2004-07-15 23:36:47.000000', NULL, 1),
(813481, 89838, 24204, '<td valign="top">Great composition...</td>', 'Great composition...', '2004-07-15 23:41:35.000000', NULL, 1),
(813496, 90261, 23929, '<td valign="top">Wouldn''t that be nice. Great piccy. Maybe if we could have seen what it was on might have had more impact.</td>', 'Wouldn''t that be nice. Great piccy. Maybe if we could have seen what it was on might have had more impact.', '2004-07-16 00:09:24.000000', NULL, 1),
(813499, 91043, 23929, '<td valign="top">Some depth of field really would have made this a 10</td>', 'Some depth of field really would have made this a 10', '2004-07-16 00:11:49.000000', NULL, 1),
(813501, 90035, 23929, '<td valign="top">Maybe if the writing was facing us? But I love this piccy - the curves are great.</td>', 'Maybe if the writing was facing us? But I love this piccy - the curves are great.', '2004-07-16 00:12:59.000000', NULL, 1),
(813502, 90840, 23939, '<td valign="top">I am speechless. There are supposed to be words.</td>', 'I am speechless. There are supposed to be words.', '2004-07-16 00:14:55.000000', NULL, 1),
(813505, 89863, 23929, '<td valign="top">Awesome. Where was this taken?</td>', 'Awesome. Where was this taken?', '2004-07-16 00:16:16.000000', NULL, 1),
(813511, 90959, 23939, '<td valign="top">It is very blurry. You can see the words. It was probally a very nice pic.</td>', 'It is very blurry. You can see the words. It was probally a very nice pic.', '2004-07-16 00:21:18.000000', NULL, 1),
(813512, 90782, 23939, '<td valign="top">I cant see anything</td>', 'I cant see anything', '2004-07-16 00:22:12.000000', NULL, 1),
(813513, 89983, 23929, '<td valign="top">I Live in Australia. Where is this grave marker? That is amazing. It makes him very real and not just a folk hero.</td>', 'I Live in Australia. Where is this grave marker? That is amazing. It makes him very real and not just a folk hero.', '2004-07-16 00:23:39.000000', NULL, 1),
(813516, 90063, 23929, '<td valign="top">Clever.</td>', 'Clever.', '2004-07-16 00:25:27.000000', NULL, 1),
(813522, 90586, 23929, '<td valign="top">Hope it doesn''t cause as much controversy as the photo in the purple challenge did! Nicely done. I think the white face''s arms could have contributed to this. I really like it.</td>', 'Hope it doesn''t cause as much controversy as the photo in the purple challenge did! Nicely done. I think the white face''s arms could have contributed to this. I really like it.', '2004-07-16 00:31:18.000000', NULL, 1),
(813525, 90258, 23929, '<td valign="top">The front wheel detracts a bit. Maybe a tighter crop?</td>', 'The front wheel detracts a bit. Maybe a tighter crop?', '2004-07-16 00:33:48.000000', NULL, 1),
(813527, 90726, 19608, '<td valign="top">Unusual.  Unique. Put a tiny globe, barely visible , in the bottom right and you have a real wowser!  As is - it''s a great submission - with excellent lighting, composiition, and exposure.  That means - one of the top bunch...</td>', 'Unusual.  Unique. Put a tiny globe, barely visible , in the bottom right and you have a real wowser!  As is - it''s a great submission - with excellent lighting, composiition, and exposure.  That means - one of the top bunch...', '2004-07-16 00:35:34.000000', NULL, 1),
(813529, 89853, 23929, '<td valign="top">VERY clever :)</td>', 'VERY clever :)', '2004-07-16 00:36:18.000000', NULL, 1),
(813532, 89993, 19608, '<td valign="top">Original. Well setup and exposed.</td>', 'Original. Well setup and exposed.', '2004-07-16 00:36:46.000000', NULL, 1),
(813536, 91023, 23929, '<td valign="top">Simply beautiful. Well done.</td>', 'Simply beautiful. Well done.', '2004-07-16 00:39:09.000000', NULL, 1),
(813537, 90839, 19608, '<td valign="top">Nice idea - along with great colors.  The cut off petal at the bottom should have been avoided as well as the triangle in the top left corner.</td>', 'Nice idea - along with great colors.  The cut off petal at the bottom should have been avoided as well as the triangle in the top left corner.', '2004-07-16 00:39:15.000000', NULL, 1),
(813542, 91022, 19785, '<td valign="top">I dont get it</td>', 'I dont get it', '2004-07-16 00:41:53.000000', NULL, 1),
(813545, 91082, 19785, '<td valign="top">I strangly like it!</td>', 'I strangly like it!', '2004-07-16 00:43:37.000000', NULL, 1),
(813559, 90850, 20481, '<td valign="top">I would''ve crop your shot either showing only the first advice or else showing both advices only, But I still think is a nice shot</td>', 'I would''ve crop your shot either showing only the first advice or else showing both advices only, But I still think is a nice shot', '2004-07-16 01:02:28.000000', NULL, 1),
(813579, 91187, 20481, '<td valign="top">I think it''s an excellent photo, so I give you a 10, would you please tell me how you did it?</td>', 'I think it''s an excellent photo, so I give you a 10, would you please tell me how you did it?', '2004-07-16 01:21:01.000000', NULL, 1),
(813589, 91035, 20481, '<td valign="top">It´s really a sad shot,but still great, congratulations!</td>', 'It´s really a sad shot,but still great, congratulations!', '2004-07-16 01:26:20.000000', NULL, 1),
(813609, 90887, 24029, '<td valign="top">Interesting composition, well shot.</td>', 'Interesting composition, well shot.', '2004-07-16 01:55:01.000000', NULL, 1),
(813610, 91058, 24029, '<td valign="top">Great DOF, the box probably spoils the image for me.</td>', 'Great DOF, the box probably spoils the image for me.', '2004-07-16 01:55:32.000000', NULL, 1),
(813611, 91009, 24029, '<td valign="top">Quite amusing and interesting.</td>', 'Quite amusing and interesting.', '2004-07-16 01:55:58.000000', NULL, 1),
(813614, 91014, 24029, '<td valign="top">Nice title, well seen and captured.</td>', 'Nice title, well seen and captured.', '2004-07-16 01:57:04.000000', NULL, 1),
(813617, 90799, 24029, '<td valign="top">Exposure is a bit strong, colours seem a bit warm. Not my favourite image to be honest, but keep trying!</td>', 'Exposure is a bit strong, colours seem a bit warm. Not my favourite image to be honest, but keep trying!', '2004-07-16 02:02:10.000000', NULL, 1),
(813620, 91023, 24029, '<td valign="top">Quite well done, nice soft focus. Lacks a little punch, but still interesting.</td>', 'Quite well done, nice soft focus. Lacks a little punch, but still interesting.', '2004-07-16 02:03:25.000000', NULL, 1),
(813621, 90008, 24029, '<td valign="top">Can''t say I like this at all, crop could be tighter to remove the black, DOF makes it look a bit washed out, bland colour and contrast. Better luck next time!</td>', 'Can''t say I like this at all, crop could be tighter to remove the black, DOF makes it look a bit washed out, bland colour and contrast. Better luck next time!', '2004-07-16 02:05:16.000000', NULL, 1),
(813622, 91114, 24029, '<td valign="top">I''d have to say this is well thought out, and well shot.</td>', 'I''d have to say this is well thought out, and well shot.', '2004-07-16 02:05:49.000000', NULL, 1),
(813623, 91110, 24029, '<td valign="top">A bit noisey, the heart could be better lit. Interesting without being captivating.</td>', 'A bit noisey, the heart could be better lit. Interesting without being captivating.', '2004-07-16 02:06:40.000000', NULL, 1),
(813625, 89875, 24029, '<td valign="top">Good detail, DOF and lighting - crumbs are a bit distracting. Nice effort.</td>', 'Good detail, DOF and lighting - crumbs are a bit distracting. Nice effort.', '2004-07-16 02:07:18.000000', NULL, 1),
(813627, 89944, 24029, '<td valign="top">Nice exposure, interesting composition. Emotive is a word I''d use to describe this.</td>', 'Nice exposure, interesting composition. Emotive is a word I''d use to describe this.', '2004-07-16 02:08:14.000000', NULL, 1),
(813628, 90634, 24029, '<td valign="top">Interesting, humourous. Not technically too sound, but interesting effects.</td>', 'Interesting, humourous. Not technically too sound, but interesting effects.', '2004-07-16 02:08:52.000000', NULL, 1),
(813629, 90334, 24029, '<td valign="top">DOF is a bit shallow, it looked interesting, but on closer inspection a little confusing.</td>', 'DOF is a bit shallow, it looked interesting, but on closer inspection a little confusing.', '2004-07-16 02:09:24.000000', NULL, 1),
(813630, 90174, 24029, '<td valign="top">Interesting, lacks a bit of contrast I think, and DOF. Otherwise, potentially very good.</td>', 'Interesting, lacks a bit of contrast I think, and DOF. Otherwise, potentially very good.', '2004-07-16 02:10:03.000000', NULL, 1),
(813631, 90160, 24029, '<td valign="top">To make it work I''d shoot lower removing the ground, and use fill flash to make the subject "pop" a bit more. Not bad however.</td>', 'To make it work I''d shoot lower removing the ground, and use fill flash to make the subject "pop" a bit more. Not bad however.', '2004-07-16 02:10:52.000000', NULL, 1),
(813632, 90738, 24029, '<td valign="top">Simple subject, not badly executed. Good DOF and composition.</td>', 'Simple subject, not badly executed. Good DOF and composition.', '2004-07-16 02:11:22.000000', NULL, 1),
(813634, 90782, 24029, '<td valign="top">A little busy but appealing. Not too bad, without being eye catching.</td>', 'A little busy but appealing. Not too bad, without being eye catching.', '2004-07-16 02:12:02.000000', NULL, 1),
(813635, 90841, 24029, '<td valign="top">Humourous, without being particularly eye drawing. Look at this, giggle, bang it''s over. Does''nt really draw your eye in.</td>', 'Humourous, without being particularly eye drawing. Look at this, giggle, bang it''s over. Does''nt really draw your eye in.', '2004-07-16 02:12:44.000000', NULL, 1),
(813636, 90198, 24029, '<td valign="top">I''d say interesting, but technique or resolution make this appear a bit sub-par.</td>', 'I''d say interesting, but technique or resolution make this appear a bit sub-par.', '2004-07-16 02:13:15.000000', NULL, 1),
(813637, 91149, 24029, '<td valign="top">Submitted a little too small, and it does''nt really catch my eye.</td>', 'Submitted a little too small, and it does''nt really catch my eye.', '2004-07-16 02:13:47.000000', NULL, 1),
(813638, 90599, 24029, '<td valign="top">Appealing composition and colour.</td>', 'Appealing composition and colour.', '2004-07-16 02:14:11.000000', NULL, 1),
(813639, 91119, 24029, '<td valign="top">This is really quite interesting, but the image really does''nt quite grab me as I fel the scene might. Nice effort.</td>', 'This is really quite interesting, but the image really does''nt quite grab me as I fel the scene might. Nice effort.', '2004-07-16 02:14:42.000000', NULL, 1),
(813641, 89992, 24029, '<td valign="top">A little plain, the tree at right should''nt be in crop. The rope at front also is a bit bothersome.</td>', 'A little plain, the tree at right should''nt be in crop. The rope at front also is a bit bothersome.', '2004-07-16 02:15:26.000000', NULL, 1),
(813643, 90816, 24029, '<td valign="top">I think a closer view, would nail it. This is well shot, good action with an appropriate theme. Not the winner, but right up there.</td>', 'I think a closer view, would nail it. This is well shot, good action with an appropriate theme. Not the winner, but right up there.', '2004-07-16 02:16:16.000000', NULL, 1),
(813644, 90337, 24029, '<td valign="top">Good use of medium, nice contrast. Appealing image, well seen.</td>', 'Good use of medium, nice contrast. Appealing image, well seen.', '2004-07-16 02:16:44.000000', NULL, 1),
(813646, 90840, 24029, '<td valign="top">A bit snap-shotty, but an interesting image of an ancient subject. Even though your title hints of a connection, I''m not sure if this will win the Words challenge.</td>', 'A bit snap-shotty, but an interesting image of an ancient subject. Even though your title hints of a connection, I''m not sure if this will win the Words challenge.', '2004-07-16 02:17:42.000000', NULL, 1),
(813648, 90288, 22011, '<td valign="top">Ummmm, Words?  I''m really lost on this one....</td>', 'Ummmm, Words?  I''m really lost on this one....', '2004-07-16 02:17:51.000000', NULL, 1),
(813649, 90424, 24029, '<td valign="top">Not sure how this was accomplished, but nicely exposed, composed, and captured.</td>', 'Not sure how this was accomplished, but nicely exposed, composed, and captured.', '2004-07-16 02:18:13.000000', NULL, 1),
(813650, 90508, 24029, '<td valign="top">Does''nt really do it for me, if the news subject was life-altering, I''d check it out.</td>', 'Does''nt really do it for me, if the news subject was life-altering, I''d check it out.', '2004-07-16 02:18:52.000000', NULL, 1),
(813651, 89865, 24029, '<td valign="top">A bit bland to be brutally honest.</td>', 'A bit bland to be brutally honest.', '2004-07-16 02:19:10.000000', NULL, 1),
(813652, 90600, 24029, '<td valign="top">Unique kind of image, close to being well captured. It just does''nt grab me.</td>', 'Unique kind of image, close to being well captured. It just does''nt grab me.', '2004-07-16 02:19:37.000000', NULL, 1),
(813653, 91030, 24029, '<td valign="top">I like this, but the lighting is all wrong. Many ways to crop this better I reckon.</td>', 'I like this, but the lighting is all wrong. Many ways to crop this better I reckon.', '2004-07-16 02:20:03.000000', NULL, 1),
(813655, 90717, 22011, '<td valign="top">What''s up with the grain/noise in this shot?  it appears to be a little underexposed, but that can''t be it..  I''m a fan of grain/noise in shots where it works, but this looks odd somehow.  A PS effect?</td>', 'What''s up with the grain/noise in this shot?  it appears to be a little underexposed, but that can''t be it..  I''m a fan of grain/noise in shots where it works, but this looks odd somehow.  A PS effect?', '2004-07-16 02:22:39.000000', NULL, 1),
(813658, 89832, 22011, '<td valign="top">The black stripe on this is quite distracting..  Almost looks like the shots you get when you have the shutter sync wrong on an old SLR...  the over exposed highlights on the fingers are also very distracting from the lenscap, a diffuser on the flash, or bounced flash would have worked much better for this I think.</td>', 'The black stripe on this is quite distracting..  Almost looks like the shots you get when you have the shutter sync wrong on an old SLR...  the over exposed highlights on the fingers are also very distracting from the lenscap, a diffuser on the flash, or bounced flash would have worked much better for this I think.', '2004-07-16 02:25:45.000000', NULL, 1),
(813659, 89787, 24029, '<td valign="top">A little confusing for me.</td>', 'A little confusing for me.', '2004-07-16 02:27:01.000000', NULL, 1),
(813660, 91011, 24029, '<td valign="top">Well thought out and interesting composition.</td>', 'Well thought out and interesting composition.', '2004-07-16 02:28:09.000000', NULL, 1),
(813661, 90716, 24029, '<td valign="top">A bit of thought and effort involved, so I''d say it''s not bad.</td>', 'A bit of thought and effort involved, so I''d say it''s not bad.', '2004-07-16 02:28:41.000000', NULL, 1),
(813663, 89903, 24029, '<td valign="top">A little too dark. Nice effort.</td>', 'A little too dark. Nice effort.', '2004-07-16 02:29:12.000000', NULL, 1),
(813665, 91184, 24029, '<td valign="top">Unique, not a bad effort.</td>', 'Unique, not a bad effort.', '2004-07-16 02:29:49.000000', NULL, 1),
(813666, 91042, 24029, '<td valign="top">Nice DOF, perhaps needing the horizon rationalised.</td>', 'Nice DOF, perhaps needing the horizon rationalised.', '2004-07-16 02:30:13.000000', NULL, 1),
(813667, 90244, 24029, '<td valign="top">Technically good, interesting subject.</td>', 'Technically good, interesting subject.', '2004-07-16 02:31:00.000000', NULL, 1),
(813668, 90728, 22011, '<td valign="top">Asside from the lack of words, this shot is a bit dark around the eye''s for a full frontal portait, and you''ve broken one of the unwritten ruls of photography, especially a woman (Albeit a young one)...  Don''t take up nostril photos... :-).</td>', 'Asside from the lack of words, this shot is a bit dark around the eye''s for a full frontal portait, and you''ve broken one of the unwritten ruls of photography, especially a woman (Albeit a young one)...  Don''t take up nostril photos... :-).', '2004-07-16 02:31:25.000000', NULL, 1),
(813669, 90854, 24029, '<td valign="top">This does''nt really get the message across effectively, but a nice try.</td>', 'This does''nt really get the message across effectively, but a nice try.', '2004-07-16 02:31:31.000000', NULL, 1),
(813670, 91118, 24029, '<td valign="top">Quite good really, perhaps needing sharper focus and more contrast to highlight the words on the rose.</td>', 'Quite good really, perhaps needing sharper focus and more contrast to highlight the words on the rose.', '2004-07-16 02:32:05.000000', NULL, 1),
(813671, 91000, 24029, '<td valign="top">Composition and DOF are great, just the message isn''t quite effective. Not bad.</td>', 'Composition and DOF are great, just the message isn''t quite effective. Not bad.', '2004-07-16 02:32:39.000000', NULL, 1),
(813672, 90476, 24029, '<td valign="top">Well exposed, unique. Not quite the winner, but a solid effort.</td>', 'Well exposed, unique. Not quite the winner, but a solid effort.', '2004-07-16 02:33:08.000000', NULL, 1),
(813673, 91012, 24029, '<td valign="top">Smoking is crap for sure, this is well shot, good exposure and sharp - but as bad as smoking is, I''m less a fan of bitten fingernails.</td>', 'Smoking is crap for sure, this is well shot, good exposure and sharp - but as bad as smoking is, I''m less a fan of bitten fingernails.', '2004-07-16 02:33:49.000000', NULL, 1),
(813676, 90164, 24029, '<td valign="top">Quite sad really, effective and emotive. Not bad.</td>', 'Quite sad really, effective and emotive. Not bad.', '2004-07-16 02:34:20.000000', NULL, 1),
(813677, 91049, 24029, '<td valign="top">Probably needs a tighter crop, it''s a little too busy as it is.</td>', 'Probably needs a tighter crop, it''s a little too busy as it is.', '2004-07-16 02:34:47.000000', NULL, 1),
(813679, 90897, 24029, '<td valign="top">Humourous, good colours, not bad really. I don''t think it will win, but it''s a good effort.</td>', 'Humourous, good colours, not bad really. I don''t think it will win, but it''s a good effort.', '2004-07-16 02:35:22.000000', NULL, 1),
(813681, 90196, 22011, '<td valign="top">Neat idea..  Did you manage to write this that well backwards, or is the image flipped?  Either way, neat..  I would have probably cropped it abouce the top of the words, but appart from that, did I mention neat?</td>', 'Neat idea..  Did you manage to write this that well backwards, or is the image flipped?  Either way, neat..  I would have probably cropped it abouce the top of the words, but appart from that, did I mention neat?', '2004-07-16 02:35:31.000000', NULL, 1),
(813682, 90062, 24029, '<td valign="top">Good effort, but I think sharp and fast shutter might have given a better spark effect.</td>', 'Good effort, but I think sharp and fast shutter might have given a better spark effect.', '2004-07-16 02:35:59.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(813683, 90177, 24029, '<td valign="top">A little warm, lighting and focus could be improved.</td>', 'A little warm, lighting and focus could be improved.', '2004-07-16 02:36:27.000000', NULL, 1),
(813684, 90132, 24029, '<td valign="top">Quite humourous and interesting, good comosition.</td>', 'Quite humourous and interesting, good comosition.', '2004-07-16 02:36:52.000000', NULL, 1),
(813685, 89838, 24029, '<td valign="top">Well composed, good DOF - simple, yet effective.</td>', 'Well composed, good DOF - simple, yet effective.', '2004-07-16 02:37:47.000000', NULL, 1),
(813687, 90746, 24029, '<td valign="top">If technically it was excellent, I''d like this alot. It''s a little soft and lacks contrast.</td>', 'If technically it was excellent, I''d like this alot. It''s a little soft and lacks contrast.', '2004-07-16 02:38:29.000000', NULL, 1),
(813689, 89845, 24029, '<td valign="top">A little small, shadow on RHS is distracting - otherwise this has potential.</td>', 'A little small, shadow on RHS is distracting - otherwise this has potential.', '2004-07-16 02:39:01.000000', NULL, 1),
(813690, 90717, 24029, '<td valign="top">Unique, but the texture does''nt really make the theme jump out at you. I like this and don''t like it at the same time.</td>', 'Unique, but the texture does''nt really make the theme jump out at you. I like this and don''t like it at the same time.', '2004-07-16 02:39:48.000000', NULL, 1),
(813692, 91025, 24029, '<td valign="top">A little too simple - lacks sharpness and contrast.</td>', 'A little too simple - lacks sharpness and contrast.', '2004-07-16 02:40:12.000000', NULL, 1),
